<?php $editing=!empty($item);$id=$editing?(int)$item->id:0;$admin_profile_id=isset($admin_profile_id)?(int)$admin_profile_id:0; ?>
<dialog id="uttp-modal-<?= $id ?>" class="admin-modal" aria-labelledby="uttp-title-<?= $id ?>"><div class="modal-head"><div><small>Daftar UTTP</small><h2 id="uttp-title-<?= $id ?>"><?= $editing?'Ubah UTTP':'Tambah UTTP' ?></h2></div><button type="button" class="modal-close" data-modal-close aria-label="Tutup">×</button></div>
<form method="post" action="<?= site_url($admin_profile_id?('petugas/pemohon/'.$admin_profile_id.'/uttp/simpan'.($editing?'/'.$id:'')):($editing?'uttp/simpan/'.$id:'uttp/simpan')) ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><div class="modal-body"><div class="form-grid"><label>Jenis UTTP<select name="uttp_type_id" required><option value="">Pilih jenis</option><?php foreach ($types as $type): if (!$type->is_active && (!$editing || (int)$item->uttp_type_id!==(int)$type->id)) continue; ?><option value="<?= (int)$type->id ?>" data-mass="<?= (int)$type->requires_capacity ?>" data-pubbm="<?= in_array($type->type_code,array('PUBBM','POMPA_UKUR'),TRUE)?'1':'0' ?>"<?= $editing && (int)$item->uttp_type_id===(int)$type->id?' selected':'' ?>><?= e($type->type_name) ?><?= $type->is_active?'':' (nonaktif)' ?></option><?php endforeach; ?></select></label><label>Nama pemilik<input name="owner_name" required minlength="3" maxlength="190" value="<?= e($editing?$item->owner_name:($profile->organization_name ?: $current_user->full_name)) ?>"></label><label>Merek<input name="brand" required maxlength="120" value="<?= e($editing?$item->brand:'') ?>"></label><label>Tipe<input name="type_name" maxlength="120" value="<?= e($editing?$item->type_name:'') ?>"></label><label>Kapasitas<input name="capacity" maxlength="120" value="<?= e($editing?$item->capacity:'') ?>"></label><label>Nomor seri <small>opsional</small><input name="serial_number" maxlength="120" value="<?= e($editing?$item->serial_number:'') ?>"></label><label data-pubbm-field>Nozzle<input name="nozzle_no" maxlength="40" value="<?= e($editing?$item->nozzle_no:'') ?>"></label><label data-pubbm-field>Dispenser<input name="dispenser_no" maxlength="40" value="<?= e($editing?$item->dispenser_no:'') ?>"></label><label data-pubbm-field>Media / produk BBM<input name="media" maxlength="80" value="<?= e($editing?$item->media:'') ?>"></label><label data-pubbm-field>Tahun pembuatan<input name="manufacture_year" maxlength="40" value="<?= e($editing?$item->manufacture_year:'') ?>"></label><label data-pubbm-field>Qmax / Qmin<input name="flow_rate" maxlength="80" value="<?= e($editing?$item->flow_rate:'') ?>"></label><label data-other-field>Daya baca<input name="readability" maxlength="80" value="<?= e($editing?$item->readability:'') ?>"></label><label class="span-2">Alamat lokasi UTTP<textarea name="service_address" required minlength="10" rows="2"><?= e($editing?$item->service_address:$profile->address) ?></textarea></label></div>
<div class="geo-picker"><strong>Titik lokasi UTTP ini</strong><p class="muted">Setiap UTTP dapat mempunyai lokasi berbeda. Isi koordinat atau geser penanda di peta.</p><div class="geo-coordinate-fields"><label>Lintang<input data-geo-lat name="latitude" type="number" step="0.0000001" min="-90" max="90" value="<?= e($editing?$item->latitude:$profile->latitude) ?>"></label><label>Bujur<input data-geo-lng name="longitude" type="number" step="0.0000001" min="-180" max="180" value="<?= e($editing?$item->longitude:$profile->longitude) ?>"></label></div><input data-geo-source type="hidden" name="location_source" value="<?= e($editing?$item->location_source:$profile->location_source) ?>"><div class="geo-actions"><button data-geo-open type="button" class="button outline small-button">Pusatkan peta</button><button data-geo-clear type="button" class="button outline small-button">Hapus titik</button></div><div class="geo-map"></div></div></div><div class="modal-actions"><button type="button" class="button outline" data-modal-close>Batal</button><button type="submit" class="button primary">Simpan UTTP</button></div></form></dialog>
